// A Sessao.data guarda a meia-noite UTC do dia — filtrar 'ontem' é de=ate=YYYY-MM-DD
const ontem = new Date(Date.now() - 24 * 60 * 60 * 1000);
const dataOntem = ontem.toLocaleDateString('en-CA', { timeZone: 'Europe/Lisbon' });
return [{ json: { dataOntem } }];

const sessoes = $json.data || [];
const out = [];
for (const s of sessoes) {
  if (s.avaliacaoEnviadaEm) continue; // já pedimos avaliação
  const cliente = s.cliente || {};
  const primeiroNome = (cliente.nome || '').split(' ')[0] || 'lá';
  const link = 'https://crm.essencewellnesspt.com/forms/feedback.html?clienteId=' + s.clienteId + '&sessaoId=' + s.id + '&t=' + s.linkToken;
  const telefone = (cliente.telefone || '').replace(/\D/g, '');
  const temWhatsapp = cliente.temWhatsapp !== false && telefone.length > 0;

  if (temWhatsapp) {
    const telefoneCompleto = telefone.length === 9 ? '351' + telefone : telefone;
    out.push({ json: { canal: 'whatsapp', sessaoId: s.id, clienteId: s.clienteId, telefone: telefoneCompleto, primeiroNome, servico: s.servico, link } });
  } else if (cliente.email) {
    const assunto = 'Como te sentes depois da sessão de ontem?';
    const emailHtml = '<!DOCTYPE html><html><body style="margin:0;padding:0;background-color:#ede7e3;"><table width="100%" border="0" cellspacing="0" cellpadding="0" style="background-color:#ede7e3;padding:40px 20px;"><tr><td align="center"><table width="100%" border="0" cellspacing="0" cellpadding="0" style="max-width:600px;background-color:#ffffff;border-top:4px solid #c9a66b;border-radius:4px;padding:40px;"><tr><td align="center" style="padding-bottom:30px;"><h1 style="margin:0;font-family:serif;color:#1c1c1c;font-size:24px;font-weight:normal;letter-spacing:1px;">Essence Wellness</h1></td></tr><tr><td style="font-family:Helvetica,Arial,sans-serif;color:#6d6d6d;font-size:16px;line-height:1.8;">Olá ' + primeiroNome + '! Como te sentes hoje, depois da sessão de ontem — mais leve, mais descansada?</td></tr><tr><td align="center" style="padding:35px 0;"><a href="' + link + '" style="background-color:#c9a66b;color:#ffffff;font-family:Helvetica,Arial,sans-serif;font-size:13px;font-weight:500;text-decoration:none;padding:14px 30px;border-radius:3px;letter-spacing:1.5px;text-transform:uppercase;display:inline-block;">Partilhar a minha experiência</a></td></tr><tr><td style="font-family:Helvetica,Arial,sans-serif;color:#6d6d6d;font-size:16px;line-height:1.8;">Obrigada pela confiança. Até muito breve!</td></tr></table></td></tr></table></body></html>';
    out.push({ json: { canal: 'email', sessaoId: s.id, clienteId: s.clienteId, email: cliente.email, assunto, emailHtml } });
  }
  // sem whatsapp e sem email: não há como contactar, ignora
}
return out;

// Calcula a hora exacta do lembrete (fim da sessão + 10 min de margem)
// para cada sessão por registar — já não filtra "ainda não chegou a hora",
// isso passou a ser responsabilidade do nó Wait no sub-workflow 05b.
function lisboaParaUTC(dataYMD, horaHHmm) {
  const comoSeFosseUTC = new Date(dataYMD + 'T' + horaHHmm + ':00Z');
  const lisboaStr = comoSeFosseUTC.toLocaleString('en-US', { timeZone: 'Europe/Lisbon' });
  const utcStr = comoSeFosseUTC.toLocaleString('en-US', { timeZone: 'UTC' });
  const offsetMs = new Date(lisboaStr).getTime() - new Date(utcStr).getTime();
  return new Date(comoSeFosseUTC.getTime() - offsetMs);
}

const BUFFER_MIN = 10;
const sessoes = ($json.data || []).filter(s =>
  (s.estado === 'agendada' || s.estado === 'confirmada') && !s.lembretePosSessaoEnviado
);

const out = [];
for (const s of sessoes) {
  if (!s.hora || !s.duracao) continue; // sem hora/duração não dá para calcular o fim
  const inicio = lisboaParaUTC(s.data.slice(0, 10), s.hora);
  const horaEnvio = new Date(inicio.getTime() + (s.duracao + BUFFER_MIN) * 60000);

  out.push({ json: {
    sessaoId: s.id,
    nomeCliente: (s.cliente && s.cliente.nome) || '',
    hora: s.hora,
    servico: s.servico || '',
    link: 'https://crm.essencewellnesspt.com/forms/pos-sessao.html?sessaoId=' + s.id + '&t=' + s.linkToken,
    esperarAte: horaEnvio.toISOString(),
  } });
}
return out;

// Janela alargada: hoje + ontem, para garantir que se o lembrete
// não disparar no próprio dia (ex: n8n em baixo), é apanhado no dia seguinte.
const hoje = new Date();
const dataHoje = hoje.toLocaleDateString('en-CA', { timeZone: 'Europe/Lisbon' });
const ontem = new Date(Date.now() - 24 * 60 * 60 * 1000);
const dataOntem = ontem.toLocaleDateString('en-CA', { timeZone: 'Europe/Lisbon' });
return [{ json: { dataHoje, dataOntem } }];

// Recorrente = já teve outra sessão realizada nos últimos 60 dias antes
// desta. A mais recente do histórico (limit=2, ordenado desc) é a de ontem
// que estamos a processar agora; a segunda é a anterior a essa.
const historico = $json.data || [];
let recorrente = false;
if (historico.length >= 2) {
  const maisRecente = new Date(historico[0].data);
  const anterior = new Date(historico[1].data);
  const diffDias = Math.round((maisRecente - anterior) / 86400000);
  recorrente = diffDias < 60;
}
return [{ json: { recorrente } }];

// Cliente recorrente (sessão há menos de 60 dias) — não pedimos o
// questionário completo outra vez tão cedo, só uma mensagem breve de
// cuidado, sem link nenhum.
const d = $('Filtrar Sem Pedido de Avaliação').item.json;
const textoWhatsapp = `Olá ${d.primeiroNome}! 🌿 Passei só para saber como estás depois da sessão de ontem. Sei que voltas sempre e isso significa muito para nós — qualquer coisa, escreve.\n\nFlora ✦ | Essence Wellness`;
const assuntoEmail = 'Como estás depois da sessão de ontem?';
const emailHtml = '<!DOCTYPE html><html><body style="margin:0;padding:0;background-color:#ede7e3;"><table width="100%" border="0" cellspacing="0" cellpadding="0" style="background-color:#ede7e3;padding:40px 20px;"><tr><td align="center"><table width="100%" border="0" cellspacing="0" cellpadding="0" style="max-width:600px;background-color:#ffffff;border-top:4px solid #c9a66b;border-radius:4px;padding:40px;"><tr><td align="center" style="padding-bottom:30px;"><h1 style="margin:0;font-family:serif;color:#1c1c1c;font-size:24px;font-weight:normal;letter-spacing:1px;">Essence Wellness</h1></td></tr><tr><td style="font-family:Helvetica,Arial,sans-serif;color:#6d6d6d;font-size:16px;line-height:1.8;">Olá ' + d.primeiroNome + '! Passei só para saber como estás depois da sessão de ontem. Sei que voltas sempre e isso significa muito para nós — qualquer coisa, escreve.</td></tr><tr><td style="font-family:Helvetica,Arial,sans-serif;color:#6d6d6d;font-size:16px;line-height:1.8;">Até muito breve!</td></tr></table></td></tr></table></body></html>';
return [{ json: { canal: d.canal, telefone: d.telefone, email: d.email, textoWhatsapp, assuntoEmail, emailHtml } }];

// Fallback: o WhatsApp falhou — reconstrói a mesma mensagem para email.
const texto = `Olá ${$json.primeiroNome}! Como te sentes hoje, depois da sessão de ontem — mais leve, mais descansada? 🌿 Se tiveres um minuto, adorava saber como foi a tua experiência: ${$json.link}

Flora ✦ | Essence Wellness`;
return [{ json: {
  to: 'geral@essencewellnesspt.com',
  subject: '⚠️ WhatsApp falhou — Pedido de Feedback (cliente)',
  body: `O envio por WhatsApp falhou (Evolution API) — aqui fica a mesma mensagem, por email:

${texto}`,
} }];

// Fallback: o WhatsApp falhou (Evolution API) — envia a MESMA mensagem por
// email em vez de a perder. Simples: sem despejo de JSON, sem aviso genérico
// de "WhatsApp desligado" (isso é só o WF15) — é só o conteúdo real.
const texto = $json.texto || $json.textoWhatsapp || '(sem conteúdo disponível — a sessão continua registada no CRM)';
return [{ json: {
  to: 'geral@essencewellnesspt.com',
  subject: '⚠️ WhatsApp falhou — Check-in Recorrente (cliente)',
  body: `O envio por WhatsApp falhou (Evolution API) — aqui fica a mesma mensagem, por email:

${texto}`,
} }];

